import json
from pathlib import Path
b=Path(__file__).parent
payload={k:json.loads((b/(v+'.json')).read_text()) for k,v in [('summary','summary'),('findings','findings'),('coverage','coverage'),('headwords','headword_coverage')]}
replacement=json.loads((b/'sentence_replacement.json').read_text()) if (b/'sentence_replacement.json').exists() else None
payload['applied']={'LANG-006':'Replaced with ohmaen I Ya. — I love you. '+replacement.get('translation_note','')+' The earlier missing-my flag is superseded by this approved contextual explanation. The simpler replacement remains in use.'} if replacement else {}
if (b/'applied_results.json').exists():
 payload['applied'].update(json.loads((b/'applied_results.json').read_text())['outcomes'])
payload['completed']=[f for f in payload['findings'] if f['id'] in payload['applied']]
payload['findings']=[f for f in payload['findings'] if f['id'] not in payload['applied']]
for f in payload['findings']:
 category=f['category']
 if category=='Example placement':
  f['plain_why']='These examples may show a related word, an ending, or a teaching point instead of ordinary use of '+', '.join(f['headwords'])+'. Each sentence is listed below so you can see the connection yourself.'
  if f['id']=='LINK-ka': f['plain_why']='Ka means without or no. Some examples here show possessive -ka instead. They belong with possession, not the negative word ka.'
  f['plain_action']='Check which examples belong with this word. Keep useful examples of related forms under a separate label. Remove links that do not belong.'
 elif category=='Duplicate records':
  f['plain_why']='The same Celan sentence and English translation are saved more than once. This is a repeated record, not a different language meaning.'
  f['plain_action']='Show one copy in the app and keep a record of all its sources.'
 elif category=='Translation variants':
  f['plain_why']='The Celan sentence is the same, but the English versions differ. Some differences may be only quotation marks or equally valid wording. They are not automatically mistakes.'
  f['plain_action']='Keep one English version on display. Save another version as a note if it adds useful meaning.'
 elif category=='App presentation':
  f['plain_why']='This item appears in the sentence area, but it is a phrase, word form, teaching example, or example of what not to write. The original audit record below shows exactly what was found.'
  f['plain_action']='Keep useful material, but label it clearly and put teaching notes apart from ordinary examples.'
 elif category=='Meaning / translation':
  word='jor' if 'jor as' in f['why'] else 'wel'
  meaning='surge or burst forth' if word=='jor' else 'sharing or unity'
  f['plain_why']='The dictionary gives '+word+' the meaning “'+meaning+'.” The English sentence below uses it differently. I need your decision about whether that use is intended.'
  f['plain_action']='Either keep this use and explain what the word means here, or replace the example with one that follows the dictionary meaning.'
 else:
  f['plain_why']=f['why'];f['plain_action']=f['proposal']
payload['summary']['pending_findings']=len(payload['findings'])
payload['summary']['completed_findings']=len(payload['completed'])
